import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DyLyN3RJ.js";const u=JSON.parse('{"title":"2026-11-02 Agent 核心研究与竞品动态","description":"","frontmatter":{"title":"2026-11-02 Agent 核心研究与竞品动态"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-02.md","filePath":"zh/runtime/daily-intelligence/2026-11-02.md","lastUpdated":1793588050000}'),p={name:"zh/runtime/daily-intelligence/2026-11-02.md"};function i(o,e,s,l,h,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_2026-11-02-agent-核心研究与竞品动态" tabindex="-1">2026-11-02 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-02-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-02 Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮重点是恢复身份、撤权和迁移：Paperclip 的挂起会话恢复从昨日未完成推进到同源实测通过，但托管/生产资格仍待验证；Langfuse 把 key 所有者撤权接入检查。全部 CodeFlowMu/FCoP 启发均为待验证线索。</p><h2 id="_1-paperclip-悬挂会话跨控制器恢复通过同源实测" tabindex="-1">1. Paperclip：悬挂会话跨控制器恢复通过同源实测 <a class="header-anchor" href="#_1-paperclip-悬挂会话跨控制器恢复通过同源实测" aria-label="Permalink to &quot;1. Paperclip：悬挂会话跨控制器恢复通过同源实测&quot;">​</a></h2><p><strong>#18554 MERGED; scoped live test passed; hosted/canary pending</strong></p><p>恢复已验证的 Runner suspension receipt，并保留旧 authority 的 launch files，避免把已安全挂起的 Runner 当成存活进程接管。上游同源 Codex/Daytona 测试通过：518 次读取、53 次保存及回读，四个回合保留 provider 会话与 native receipts。浏览器托管重连、十次 Railway 部署和生产 canary 仍未完成；初次 CI 失败与清理遗漏也留档。</p><p>学习价值高、竞争风险高；主雷达恢复成熟度局部上调。FCoP 待验证：悬挂回执、物理 sandbox 与会话身份须共同验证。值得互动：receipt 读取中断、源 authority 文件的回收时机。</p><p><a href="https://github.com/paperclipai/paperclip/pull/18554" target="_blank" rel="noreferrer">PR #18554</a></p><h2 id="_2-langfuse-gateway-key-重新检查所有者权限" tabindex="-1">2. Langfuse：Gateway key 重新检查所有者权限 <a class="header-anchor" href="#_2-langfuse-gateway-key-重新检查所有者权限" aria-label="Permalink to &quot;2. Langfuse：Gateway key 重新检查所有者权限&quot;">​</a></h2><p><strong>#19542 MERGED; release not verified</strong></p><p>此前只查 key 自身角色，绕过应用的角色变更可能让已降权/离职用户的 key 继续调用。现在 resolve cache miss 时同步检查 owner 的组织权限，不具 gateway:invoke 返回 403；service-account key 不变。带外变更受缓存 TTL 约束，默认最多约 60 秒；应用内降权原本会立即删除 key 并驱逐缓存。</p><p>待验证：凭据有效不代表所有者仍有权限，撤权时延要单列。值得互动：缓存失效、恢复角色和 service-account 归属边界。</p><p><a href="https://github.com/langfuse/langfuse/pull/19542" target="_blank" rel="noreferrer">PR #19542</a></p><h2 id="_3-ag2-a2a-按产物身份统一流式与轮询账本" tabindex="-1">3. AG2：A2A 按产物身份统一流式与轮询账本 <a class="header-anchor" href="#_3-ag2-a2a-按产物身份统一流式与轮询账本" aria-label="Permalink to &quot;3. AG2：A2A 按产物身份统一流式与轮询账本&quot;">​</a></h2><p><strong>#3494 MERGED; release not verified</strong></p><p>每个 artifact 保存完整内容与当轮 baseline，流增量和轮询快照进入同一账本，避免只保留首次轮询前缀、重复工具调用和旧轮文本混入。取消任务不再作为普通答案，检查过的接口身份与真正发送目标保持一致；服务端也处理终态取消竞争与 artifact 完成语义。</p><p>FCoP 待验证：重连/轮询不能靠字符串拼接猜完成，须有 artifact 与 turn 身份。值得互动：同 ID 跨轮复用、全量重发、混合 part 的一致性。</p><p><a href="https://github.com/ag2ai/ag2/pull/3494" target="_blank" rel="noreferrer">PR #3494</a></p><h2 id="_4-openhands-重复暂停可恢复-历史加载不依赖不可用运行时" tabindex="-1">4. OpenHands：重复暂停可恢复，历史加载不依赖不可用运行时 <a class="header-anchor" href="#_4-openhands-重复暂停可恢复-历史加载不依赖不可用运行时" aria-label="Permalink to &quot;4. OpenHands：重复暂停可恢复，历史加载不依赖不可用运行时&quot;">​</a></h2><p><strong>#19186/#19194 MERGED; release not verified</strong></p><p>新消息/重试可再次唤醒已被容量策略暂停的 sandbox，合并正在进行的 resume，闲置 tab 不反复唤醒；导航/组织切换淘汰旧尝试。历史加载跳过 PAUSED/MISSING/ERROR runtime 的 count 请求。上游普通短会话小样本没有证明常态加载提速，不能把注入延迟实验当日常性能提升。</p><p>待验证：用户触发恢复与后台观察分开，保存历史不等于 runtime 存活。值得互动：旧 timeout 对新 Retry 的隔离，以及历史缺失与重放覆盖。</p><p><a href="https://github.com/OpenHands/OpenHands/pull/19186" target="_blank" rel="noreferrer">PR #19186</a> · <a href="https://github.com/OpenHands/OpenHands/pull/19194" target="_blank" rel="noreferrer">PR #19194</a></p><h2 id="_5-paradev-应用目录与仓库配置迁移保留旧路径兼容" tabindex="-1">5. Paradev：应用目录与仓库配置迁移保留旧路径兼容 <a class="header-anchor" href="#_5-paradev-应用目录与仓库配置迁移保留旧路径兼容" aria-label="Permalink to &quot;5. Paradev：应用目录与仓库配置迁移保留旧路径兼容&quot;">​</a></h2><p><strong>#9158/#9248 MERGED; release not verified</strong></p><p>应用 home 从 ~/.superset 移到 ~/.paradev，停止旧 host-service 前验证 PID 命令行，保留 pty daemon、旧路径 symlink、Claude session 映射并修复 worktree/数据库路径；失败继续旧 home，下次重试。仓库配置优先真正存在的主 config，而不是目录或零散 ports 文件，避免新目录遮住旧配置；SUPERSET_HOME_DIR 变量仍保留。</p><p>学习价值高、竞争风险中高，主雷达提高升级/兼容关注。待验证：品牌改名涉及绝对路径、会话和长存进程。值得互动：迁移并发、名称冲突、旧客户端附件显示和回滚。</p><p><a href="https://github.com/ParadevAI/Paradev/pull/9158" target="_blank" rel="noreferrer">PR #9158</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9248" target="_blank" rel="noreferrer">PR #9248</a></p><h2 id="_6-orkas-ipc-日志截断私密错误-调用者仍保留错误细节" tabindex="-1">6. Orkas：IPC 日志截断私密错误，调用者仍保留错误细节 <a class="header-anchor" href="#_6-orkas-ipc-日志截断私密错误-调用者仍保留错误细节" aria-label="Permalink to &quot;6. Orkas：IPC 日志截断私密错误，调用者仍保留错误细节&quot;">​</a></h2><p><strong>#154 MERGED; release not verified</strong></p><p>在 IPC logging 边界归纳失败文本，覆盖返回失败、异常、导入和流失败；不改变调用者收到的原始错误回复。上游隐私回归、真实 Electron 启动和 automation 重启旅程通过，不把这些当本地实测或全面泄漏审计。</p><p>学习价值中高、竞争风险中，主雷达保留 privacy/诊断观察。待验证：用户诊断细节与可收集日志需不同边界。值得互动：嵌套错误、重试去重和流清理时的脱敏覆盖。</p><p><a href="https://github.com/Orkas-AI/Orkas/pull/154" target="_blank" rel="noreferrer">PR #154</a></p><h2 id="共振、分类与覆盖" tabindex="-1">共振、分类与覆盖 <a class="header-anchor" href="#共振、分类与覆盖" aria-label="Permalink to &quot;共振、分类与覆盖&quot;">​</a></h2><p>恢复必须保留原会话/产物/路径身份；凭据本身有效不能替代所有者权限；实验注入、局部通过和生产验收分别记录。本轮工程实验、文章、开发评审和外部评论均为 0。</p><p>实际起点 2026-11-02 10:46:49（Asia/Shanghai）；从上轮 2026-11-01 22:26:48 基线去重。先经 GitHub 工具读最新 Registry，仍 47 人。人物与来源多对多；赵越名字固定，未确认其新代码；六位治理对象关系保留，bulbasaur 不是 AGENTSAFE 官方 Artifact。88 仓库提交核查已保存；Orca 首 100 条未分页完成，TSA 404。Issue 每库最多 10 条、Release 最多 3 条；达到上限均视部分核查，不推进其完整水位。连接工具在大批量查询时多次中断，随后改为四并发重新查询并保存；本轮覆盖弱于此前完整分页，不能称全源无遗漏。核心作者参与以原 PR 作者/合入者为据。未穷尽 Discussion、Roadmap、架构及 License，也不把未验证合入项写成发行。</p><p>公开 X/人物检索、Cursor changelog 和 Audit Commons 独立核查；未确认窗口内个人新帖，不能称穷尽社交。官网可见旧材料不算新增，GitHub 两链接不算两种来源。</p><p>日档仅写规定双语文件与两索引，沿用现有站点、布局、快照和入口；main 回读及本次 gh-pages/Pages 与双语点击验收另存本地回执，不预先声称上线。未改 Research Runtime 业务事实、调度、候选或生命周期。</p>',37)])])}const g=a(p,[["render",i]]);export{u as __pageData,g as default};
